from bank_common import *

def multi(b,id,prompt,options,correct,reason,page,label,formula='',description='',**kwargs):
 return b.add(id,5,'Утверждения и контрпримеры',prompt,';'.join(map(str,correct)),[
 stage('Нужный факт',block('Утверждение должно следовать из условия для каждого допустимого примера.',formula)),
 stage('Что известно',block(description or 'Отделяем условия задачи от дополнительных предположений.')),
 stage('Проверяем выводы',block(reason)),
 stage('Ответ',block('Номера выбранных утверждений: '+', '.join(map(str,correct))))],page,label,kind='multi',options=[{'value':str(i),'label':v} for i,v in enumerate(options,1)],instruction=kwargs.pop('instruction','Выбери все верные утверждения.'),description=description,**kwargs)

def populate(b):
 E=[(-1)**n/(n+1)**2,(2+(-1)**n)/n,(4*n*n+1)/(3*n*n+2),(2-n*n)/(n*n),(-1)**(n-1)*n-3,n**(-n),1+n*s.sin(s.pi*n/2),n*n/2**n,s.factorial(n)/1000**n,(1+1/n)**(n+1),n-1/n,n/(2*n-3),-(n*n+1)/n**2,3**n/n,-s.sqrt(n),(-1)**n/(2*n),n/(3*n-2),(3*n+2)/(n+1),s.cos(s.pi*n/2),n/5**n,-n*(2+(-1)**n),s.sqrt(n)/(100+n),n+100/n,(-1)**(n-1)*n-3,(3*n+5)/(2*n-3),1+(-1)**n/n,n*s.cos(s.pi*(n-1)/2),s.sin((n-1)*s.pi/4),-n*n/2**n]
 answers=[3,3,1,2,3,2,3,3,3,2,1,3,1,1,2,3,2,1,3,2,3,3,3,3,3,3,3,3,3]
 for i,(f,a) in enumerate(zip(E,answers),1):
  delta=s.factor(f.subs(n,n+1)-f)
  if a==3:
   samples=list(range(1,9))+[99,100,101,999,1000,1001]
   signs=[]
   for k in samples:
    d=delta.subs(n,k)
    if d.is_positive:signs.append((k,1))
    if d.is_negative:signs.append((k,-1))
   pos=next((k for k,v in signs if v==1),None);neg=next((k for k,v in signs if v==-1),None)
   assert pos and neg,(i,pos,neg)
   key=r'x_{'+str(pos+1)+r'}-x_{'+str(pos)+r'}>0,\quad x_{'+str(neg+1)+r'}-x_{'+str(neg)+r'}<0'
   first=r'x_n='+tex(f)
  elif i==10:
   first=r'g(t)=(t+1)\ln(1+1/t),\quad x_n=e^{g(n)}'
   key=r'g^\prime(t)=\ln(1+1/t)-1/t<0\quad(t>0)'
  elif i in [6,14,20]:
   first=r'\frac{x_{n+1}}{x_n}='+tex(s.simplify(f.subs(n,n+1)/f));key=r'\frac{x_{n+1}}{x_n}>1' if a==1 else r'0<\frac{x_{n+1}}{x_n}<1'
  else:first=r'x_{n+1}-x_n='+tex(delta);key=r'x_{n+1}-x_n>0\quad(n\ge1)' if a==1 else r'x_{n+1}-x_n<0\quad(n\ge1)'
  b.add(f'monotonic-{i:02}',2,'Монотонность последовательности',r'x_n='+tex(f)+r',\quad n=1,2,\ldots',str(a),four(r'\Delta_n=x_{n+1}-x_n;\quad\Delta_n>0\Rightarrow\nearrow,\quad\Delta_n<0\Rightarrow\searrow',first,key,r'\boxed{\text{'+{1:'Возрастает',2:'Убывает',3:'Не является монотонной'}[a]+'}}'),1,f'Банк · задача 1 · пример {i}',kind='choice',instruction='Определи монотонность всей последовательности, начиная с n = 1.',options=[{'value':'1','label':'Возрастает'},{'value':'2','label':'Убывает'},{'value':'3','label':'Не является монотонной'}])
 # All ten original sequence assertion sets ask for false statements.
 seq=[
 (r'\lim(x_{n+1}-x_n)=0',['Последовательность сходится','Последовательность ограничена','Последовательность монотонна'],[1,2,3],'xₙ = √n расходится и не ограничена. xₙ = (−1)ⁿ/n не монотонна.'),
 (r'\lim x_{n+1}/x_n=1',['Последовательность сходится','Последовательность ограничена','Последовательность монотонна'],[1,2,3],'xₙ = n опровергает первые два вывода. xₙ = 1 + (−1)ⁿ/n опровергает монотонность (нулевой первый член можно заменить на 1).'),
 (r'\lim x_{n+1}/x_n=2',['Монотонно возрастает','Ограничена','Расходится'],[1,2],'При больших n модуль отношения больше 3/2, поэтому |xₙ| → ∞. Но xₙ = −2ⁿ убывает.'),
 (r'x_n\to a,\quad x_ny_n\to b',['xₙ ограничена','yₙ сходится','yₙ ограничена'],[2,3],'Сходящаяся xₙ ограничена. Для xₙ = 1/n², yₙ = n произведение стремится к нулю, но yₙ не ограничена.'),
 (r'\lim(x_{n+1}-x_n)=2',['Расходится','Монотонно возрастает','Ограничена'],[2,3],'Разности начиная с некоторого номера больше 1, значит xₙ → +∞. Начальные члены могут нарушать монотонность всей последовательности.'),
 (r'\lim(x_{n+1}+x_n)=0',['Сходится','Ограничена','Расходится'],[1,2,3],'xₙ = (−1)ⁿ√n не ограничена и расходится, но сумма соседних стремится к 0. xₙ = 1/n сходится.'),
 (r'x_n^2\to a',['xₙ сходится','xₙ ограничена','|xₙ| сходится'],[1],'a ≥ 0, |xₙ| → √a, поэтому xₙ ограничена. xₙ = (−1)ⁿ показывает, что сама xₙ может не сходиться.'),
 (r'x_n/y_n\to a,\quad x_ny_n\to b,\quad y_n\ne0',['xₙ сходится','xₙ ограничена','yₙ сходится'],[1,3],'xₙ² = (xₙ/yₙ)(xₙyₙ) сходится, значит xₙ ограничена. xₙ = yₙ = (−1)ⁿ опровергает сходимость обеих.'),
 (r'x_n+y_n\to a,\quad x_n-y_n\to b,\quad y_n\ne0',['xₙ сходится','xₙ/yₙ сходится','yₙ ограничена'],[2],'xₙ и yₙ получаются полусуммой и полуразностью. Но xₙ = 1, yₙ = (−1)ⁿ/n дают расходящееся отношение.'),
 (r'\lim x_nx_{n+1}=1',['xₙ ограничена','lim xₙ = 1','xₙ расходится'],[1,2,3],'Для x₂ₖ = k, x₂ₖ₊₁ = 1/k соседние произведения равны 1 или (k+1)/k: ограниченности нет. Постоянная −1 опровергает предел 1, постоянная 1 опровергает обязательную расходимость.')]
 for i,(p,options,correct,reason) in enumerate(seq,1):multi(b,f'sequence-theory-{i:02}',p,options,correct,reason,1 if i<10 else 2,f'Банк · задача 1 · утверждения {i}',instruction='Выбери все НЕВЕРНЫЕ утверждения: те, которые не обязаны следовать из условия.')
 ext=['Точка максимума','Точка минимума','Точка перегиба','Требуется дополнительное исследование']
 fun=[
 (r'f^\prime(x_0)=0,\quad f^{\prime\prime}(x_0)<0',ext,[1],'По признаку второй производной это строгий локальный максимум.',2),
 (r'f^\prime(x_0)=f^{\prime\prime}(x_0)=0',ext,[4],'x⁴, −x⁴, x³ при x₀ = 0 дают минимум, максимум и перегиб: одного условия недостаточно.',2),
 (r'f^{\prime\prime}(x_0)=f^{\prime\prime\prime}(x_0)=0',ext,[4],'x⁴ и x⁵ при нуле дают разные виды поведения. Нужны дополнительные сведения.',2),
 (r'f^2\text{ дифференцируема в }x_0',['f непрерывна в x₀','f непрерывна в некоторой окрестности','f дифференцируема в x₀','f дифференцируема в некоторой окрестности','Нет правильных утверждений'],[5],'Здесь f² — квадрат функции. Для f(x) = 1 при x ≥ 0 и −1 при x < 0 квадрат равен 1 и дифференцируем, а f имеет скачок в нуле.',3),
 (r'f\in C^3,\quad f^{\prime\prime}(x_0)=0,\quad f^{\prime\prime\prime}(x_0)>0',ext,[3],'Вторая производная меняет знак: вблизи x₀ она имеет знак x−x₀.',3),
 (r'f_x,\ f_y\text{ непрерывны в }M_0',['f непрерывна в M₀','f дифференцируема в M₀','Предел f при M → M₀ существует','f определена в некоторой окрестности M₀','Нет правильных утверждений'],[1,2,3,4],'В стандартной формулировке частные производные существуют в окрестности и непрерывны в M₀. Это достаточный признак дифференцируемости; она влечёт непрерывность и существование предела.',3),
 (r'f^\prime(x_0)=f^{\prime\prime}(x_0)=f^{\prime\prime\prime}(x_0)=0,\quad f^{(4)}(x_0)<0',ext,[1],'Первая ненулевая производная имеет чётный порядок и отрицательна: f(x)−f(x₀) = f⁽⁴⁾(x₀)(x−x₀)⁴/24 + o((x−x₀)⁴).',3),
 (r'f\in C^3,\quad f^{\prime\prime}(x_0)=0,\quad f^{\prime\prime\prime}(x_0)<0',ext,[3],'Вторая производная меняет знак; это достаточный признак перегиба.',3),
 (r'f_x(M_0),\ f_y(M_0)\text{ существуют}',['f непрерывна в M₀','f дифференцируема в M₀','Предел f при M → M₀ существует','f определена в некоторой окрестности M₀','Нет правильных утверждений'],[4],'В стандартной постановке f задана в окрестности M₀. Существования частных производных недостаточно для непрерывности: f = xy/(x²+y²), f(0,0)=0 имеет обе частные производные в нуле, но вдоль y=x равна 1/2.',3),
 (r'f\in C[a,b],\quad f\text{ дифференцируема на }(a,b)',['Достигает наибольшего значения на [a,b]','Ограничена, но максимум может не достигаться','f′ ограничена на (a,b)','Существует точка, где f′ = 0'],[1],'Теорема Вейерштрасса гарантирует максимум. Производная √x не ограничена на (0,1). Для f(x)=x производная нигде не равна нулю.',4)]
 for i,(p,options,correct,reason,page) in enumerate(fun,1):
  task=multi(b,f'function-theory-{i:02}',p,options,correct,reason,page,f'Банк · задача 2 · утверждения {i}')
  if i in [6,9]:task['description']='Используется стандартная учебная постановка: функция задана в некоторой открытой окрестности M₀.'
 task=multi(b,'demo-theory',r'f\in C[a,b]',['А. Достигает максимума в некоторой точке [a,b]','Б. Имеет производную хотя бы в одной точке [a,b]','В. Ограничена на [a,b]','Г. Существует конечный предел при x → a по области определения'],[1,3,4],'Теорема Вейерштрасса гарантирует максимум и ограниченность. Непрерывность в левом конце даёт правый предел f(a). Непрерывная функция может не иметь производной ни в одной точке (пример Вейерштрасса).',2,'Демо · №5',r'\lim_{x\to a+}f(x)=f(a)',description='Предел у левого конца отрезка берётся по области определения, справа.');task['sources']=[source(2,'№5','demo')]
 oral(b)

def oral(b):
 # These are authored self-check questions, linked to the exact oral-topic list.
 rows=[
 ('Предел последовательности. Подпоследовательность, частичный предел','Если xₙ → a, что верно о любой подпоследовательности?',['Стремится к тому же a','Может стремиться к любому числу','Всегда постоянна'],[1],r'\forall\varepsilon>0\ \exists N\ \forall n>N:\ |x_n-a|<\varepsilon','Индексы подпоследовательности возрастают и тоже уходят в бесконечность.'),
 ('Критерий Коши. Свойства сходящихся последовательностей','Выбери верные утверждения для последовательностей в ℝ.',['Сходится тогда и только тогда, когда фундаментальна','Любая ограниченная последовательность сходится','Если aₙ ≤ xₙ ≤ bₙ и aₙ,bₙ → L, то xₙ → L'],[1,3],r'\forall\varepsilon>0\ \exists N:\ m,n>N\Rightarrow|x_n-x_m|<\varepsilon','Критерий Коши использует полноту ℝ. Ограниченная (−1)ⁿ не сходится. Третье утверждение — теорема о промежуточной последовательности.'),
 ('Предел функции. Первый замечательный предел','При x → 0 какие пределы равны 1?',['sin x / x','sin(3x) / x','sin(3x) / (3x)'],[1,3],r'\lim_{u\to0}\sin u/u=1','В аргументе и знаменателе должен стоять один и тот же u; во втором варианте предел равен 3.'),
 ('Бесконечно малые и бесконечно большие функции','Если α(x) → 0 и α(x) ≠ 0 в проколотой окрестности, то…',['|1/α(x)| → ∞','1/α(x) всегда → +∞','α(x) обязательно равна нулю рядом с точкой'],[1],r'\alpha\to0\Longleftrightarrow |1/\alpha|\to\infty','Знак α может меняться. Например α(x)=x при двустороннем стремлении к нулю.'),
 ('Произведение бесконечно малой и ограниченной','При α → 0 и ограниченной β чему стремится αβ?',['К нулю','Обязательно к единице','Предела никогда нет'],[1],r'|\alpha\beta|\le M|\alpha|\to0','Ограниченность β даёт одну постоянную оценку M в нужной окрестности.'),
 ('Второй замечательный предел. Степенные неопределённости','Какие формулы применимы при положительном A?',['ln(Aᴮ)=B ln A','Если A → 1 и (A−1)B → L конечен, то Aᴮ → eᴸ','Любая форма 1^∞ имеет ответ e'],[1,2],r'A^B=e^{B\ln A},\quad\ln(1+u)\sim u','У показателя после преобразования может быть любой конечный предел L.'),
 ('Эквивалентность бесконечно малых','Какие эквивалентности верны при x → 0?',['1−cos x ~ x²/2','sin(3x) ~ x','ln(1+x) ~ x'],[1,3],r'\alpha\sim\beta\Longleftrightarrow\alpha/\beta\to1','sin(3x) ~ 3x. Не теряй коэффициент сложного аргумента.'),
 ('Разность эквивалентных. Замена в отношении','Какие утверждения верны?',['Из α ~ β следует α−β = o(β)','В разности можно всегда независимо заменять слагаемые эквивалентными','В отношении можно заменять ненулевые множители эквивалентными'],[1,3],r'\frac{\alpha-\beta}{\beta}=\frac\alpha\beta-1\to0','В разности ведущие члены могут сократиться. Например sin x − x нельзя заменить на x − x для нахождения первого ненулевого порядка.'),
 ('Непрерывность в точке. Арифметические действия и композиция','Что верно для непрерывных f и g в x₀?',['f+g и fg непрерывны','f/g непрерывна, если g(x₀) ≠ 0','f/g непрерывна даже при g(x₀)=0'],[1,2],r'\lim_{x\to x_0}f(x)=f(x_0)','Для композиции внешняя функция должна быть непрерывна в значении внутренней.'),
 ('Непрерывность на отрезке','Что гарантирует непрерывность на [a,b]?',['Ограниченность и достижение максимума и минимума','Принимает каждое промежуточное значение','Производная существует всюду'],[1,2],r'm\le f(x)\le M,\quad m=\min f,\ M=\max f','Это теоремы Вейерштрасса и о промежуточном значении. |x| непрерывна, но не дифференцируема в нуле.'),
 ('Точки разрыва и классификация','Если оба конечных односторонних предела существуют и различаются, это…',['Устранимый разрыв','Скачок (разрыв первого рода)','Обязательно бесконечный разрыв'],[2],r'f(a-0)\ne f(a+0),\quad |f(a\pm0)|<\infty','При равных конечных пределах и неподходящем значении f(a) разрыв был бы устранимым.'),
 ('Производная: геометрический и механический смысл','Какие смыслы имеет f′(x₀)?',['Угловой коэффициент касательной','Скорость, если f — координата от времени','Площадь под графиком'],[1,2],r'f^\prime(x_0)=\lim_{h\to0}\frac{f(x_0+h)-f(x_0)}h','Касательная: y=f(x₀)+f′(x₀)(x−x₀).'),
 ('Дифференцируемость и непрерывность','Какие импликации верны?',['Дифференцируема ⇒ непрерывна','Непрерывна ⇒ дифференцируема','Разрыв ⇒ конечной производной нет'],[1,3],r'\Delta f=f^\prime(x_0)\Delta x+o(\Delta x)','Контрпример ко второй: |x| в нуле.'),
 ('Арифметические действия с производными','Какие формулы верны?',['(uv)′=u′v+uv′','(u/v)′=(u′v−uv′)/v²','(uv)′=u′v′'],[1,2],r'(u+v)^\prime=u^\prime+v^\prime','Для частного дополнительно нужно v ≠ 0.'),
 ('Таблица производных','Какие производные указаны верно?',['(ln x)′ = 1/x при x>0','(arctan x)′ = 1/(1+x²)','(cos x)′ = sin x'],[1,2],r'(\sin x)^\prime=\cos x,\quad(\cos x)^\prime=-\sin x','У косинуса отрицательный знак; (eˣ)′=eˣ, (aˣ)′=aˣ ln a.'),
 ('Сложная и обратная функции','Какие формулы верны при выполнении условий?',['(F(u(x)))′=F′(u(x))u′(x)','(f⁻¹)′(f(x))=1/f′(x), если f′(x)≠0','(sin(3x))′=cos(3x)'],[1,2],r'(\sin3x)^\prime=3\cos3x','Для обратной функции нужна локальная обратимость; для сложной не теряй внутреннюю производную.'),
 ('Дифференциал и инвариантность','Что верно?',['dy=f′(x)dx','Δy=dy+o(Δx)','dy всегда точно равно Δy для любой Δx'],[1,2],r'dy=f^\prime(x)\,dx,\quad dx=\Delta x','Дифференциал — линейная главная часть приращения. Для сложной зависимости сохраняется форма dy=f′(u)du.'),
 ('Теорема Ролля','Какие условия нужны для заключения f′(c)=0 при c∈(a,b)?',['Непрерывность на [a,b]','Дифференцируемость на (a,b)','f(a)=f(b)'],[1,2,3],r'\exists c\in(a,b):\ f^\prime(c)=0','Все три условия входят в теорему. Геометрически существует горизонтальная касательная.'),
 ('Теоремы Лагранжа и Коши','Какие утверждения верны при стандартных условиях теорем?',['f(b)−f(a)=f′(c)(b−a)','Для Коши: (f(b)−f(a))g′(c)=(g(b)−g(a))f′(c)','В теореме Лагранжа обязательно f(a)=f(b)'],[1,2],r'\frac{f(b)-f(a)}{b-a}=f^\prime(c)','Нужны непрерывность на отрезке и дифференцируемость внутри. Равенство концов требуется для Ролля.'),
 ('Правило Лопиталя','Какие формы допускают применение Лопиталя после проверки условий?',['0/0','∞/∞','5/0 без преобразований'],[1,2],r'\lim f/g=\lim f^\prime/g^\prime','Функции дифференцируемы в проколотой окрестности, g′≠0, предел отношения производных существует (в том числе бесконечный). Другие неопределённости сначала приводят к дроби.'),
 ('Многочлен и формула Тейлора','Какой коэффициент у (x−a)ᵏ?',['f⁽ᵏ⁾(a)/k!','f⁽ᵏ⁾(a)','f(a)/k'],[1],r'P_n(x)=\sum_{k=0}^n\frac{f^{(k)}(a)}{k!}(x-a)^k','Формула Тейлора записывает f=Pₙ+остаток.'),
 ('Остаток Тейлора: Пеано и Лагранж','Какие записи верны при соответствующих условиях?',['Rₙ=o((x−a)ⁿ) — Пеано','Rₙ=f⁽ⁿ⁺¹⁾(ξ)(x−a)ⁿ⁺¹/(n+1)! — Лагранж','Rₙ всегда равен нулю'],[1,2],r'\xi\text{ лежит между }a\text{ и }x','Для Лагранжа нужна производная порядка n+1 на соответствующем интервале.'),
 ('Локальный экстремум: условия','Какие утверждения верны для внутренней точки?',['При экстремуме и существующей производной f′(x₀)=0','f′(x₀)=0 само по себе гарантирует экстремум','Смена f′ с плюса на минус даёт максимум'],[1,3],r'f^\prime(x_0)=0\text{ — необходимое, но не достаточное условие}','x³ при нуле имеет нулевую производную, но экстремума нет.'),
 ('Вторая производная и перегиб','Какие утверждения верны?',['При f″>0 производная возрастает','Перегиб требует смены выпуклости в точке графика','Любой нуль f″ автоматически является перегибом'],[1,2],r'f^{\prime\prime}(x_0)=0\text{ — только кандидат}','x⁴: f″(0)=0, но знак f″ не меняется. Точка должна принадлежать графику.'),
 ('Асимптоты. Наклонная асимптота','Какие формулы задают y=kx+b при x→+∞?',['k=lim f(x)/x','b=lim(f(x)−kx)','b=lim f(x) при любом k'],[1,2],r'\lim_{x\to+\infty}(f(x)-kx-b)=0','Оба предела для k и b должны быть конечными. На −∞ вычисляются отдельно. k=0 даёт горизонтальную асимптоту.'),
 ('Частные и смешанные производные','Что достаточно для равенства fₓᵧ(M)=fᵧₓ(M)?',['Обе смешанные производные непрерывны в окрестности M','Только существуют в самой точке M','Любая функция обладает этим равенством'],[1],r'f_{xy}=f_{yx}\quad\text{при условиях теоремы Шварца}','При частном дифференцировании остальные независимые переменные фиксируют.'),
 ('Дифференцируемость нескольких переменных. Дифференциал','Какие утверждения верны?',['df=fₓdx+fᵧdy для дифференцируемой функции','Дифференцируемость влечёт непрерывность','Существования частных производных в точке всегда достаточно'],[1,2],r'\Delta f=f_x\Delta x+f_y\Delta y+o(\sqrt{\Delta x^2+\Delta y^2})','Непрерывность частных в окрестности точки — достаточное условие; одно существование в точке недостаточно.'),
 ('Экстремум нескольких переменных: необходимое условие','Внутренний локальный экстремум дифференцируемой f(x,y) требует…',['fₓ=fᵧ=0','fₓ+fᵧ=1','Любая стационарная точка автоматически экстремум'],[1],r'\nabla f(M_0)=0','Нулевой градиент необходим, но седловая f=x²−y² показывает недостаточность.')]
 for i,(title,question,options,correct,formula,reason) in enumerate(rows,1):
  task=multi(b,f'oral-{i:02}',r'\text{Теоретический вопрос '+str(i)+'}',options,correct,reason,1 if i<=21 else 2,f'Теория · вопрос {i}',formula,question,origin='extra',note='Авторский вопрос для самопроверки по теме из теоретического списка. Полный устный ответ нужно уметь объяснить словами.')
  task['topic']=title;task['sources']=[source(1 if i<=21 else 2,f'Тема {i}','theory')]
